import { and, asc, desc, eq, getTableColumns, gt, isNull, lt, or, sql } from "drizzle-orm";
import { newId } from "@coding-cowboys/scorebrawl-util/id-util";
import type { DrizzleDB } from "../db";
import { withTransaction } from "../db";
import { league as organization } from "../db/schema/auth-schema";
import {
	season,
	seasonPlayer,
	fixture,
	leagueTeam,
	player,
	type scoreType,
	match,
} from "../db/schema/league-schema";
import { slugifyWithCustomReplacement } from "./slug";

export interface SeasonCreateInput {
	id?: string;
	name: string;
	slug?: string;
	initialScore: number;
	scoreType: (typeof scoreType)[number];
	kFactor: number;
	startDate: Date;
	endDate?: Date;
	rounds?: number;
	leagueId: string;
	userId: string;
}

export interface SeasonEditInput {
	seasonId: string;
	name?: string;
	startDate?: Date;
	endDate?: Date;
	initialScore?: number;
	scoreType?: (typeof scoreType)[number];
	kFactor?: number;
	userId: string;
}

export const getCountInfo = async ({ db, seasonSlug }: { db: DrizzleDB; seasonSlug: string }) => {
	const [counts] = await db
		.select({
			matchCount: sql<number>`(
				SELECT count(*) FROM ${match}
				INNER JOIN ${season} s ON ${match.seasonId} = s.id
				WHERE s.slug = ${seasonSlug}
			)`,
			teamCount: sql<number>`(
				SELECT count(*) FROM ${leagueTeam}
				WHERE ${leagueTeam.leagueId} = (SELECT s.league_id FROM ${season} s WHERE s.slug = ${seasonSlug})
			)`,
			playerCount: sql<number>`(
				SELECT count(*) FROM ${seasonPlayer}
				INNER JOIN ${season} s ON ${seasonPlayer.seasonId} = s.id
				WHERE s.slug = ${seasonSlug}
			)`,
		})
		.from(sql`(SELECT 1)`);

	return {
		matchCount: counts?.matchCount || 0,
		teamCount: counts?.teamCount || 0,
		playerCount: counts?.playerCount || 0,
	};
};

export const getCountInfoById = async ({ db, seasonId }: { db: DrizzleDB; seasonId: string }) => {
	const [counts] = await db
		.select({
			matchCount: sql<number>`(
				SELECT count(*) FROM ${match}
				WHERE ${match.seasonId} = ${seasonId}
			)`,
			teamCount: sql<number>`(
				SELECT count(*) FROM ${leagueTeam}
				WHERE ${leagueTeam.leagueId} = (SELECT s.league_id FROM ${season} s WHERE s.id = ${seasonId})
			)`,
			playerCount: sql<number>`(
				SELECT count(*) FROM ${seasonPlayer}
				WHERE ${seasonPlayer.seasonId} = ${seasonId}
			)`,
		})
		.from(sql`(SELECT 1)`);

	return {
		matchCount: counts?.matchCount || 0,
		teamCount: counts?.teamCount || 0,
		playerCount: counts?.playerCount || 0,
	};
};

export const getById = async ({ db, seasonId }: { db: DrizzleDB; seasonId: string }) => {
	const [comp] = await db.select().from(season).where(eq(season.id, seasonId));
	if (!comp) {
		throw new Error("Season not found");
	}
	return comp;
};

export const getBySlug = async ({
	db,
	seasonSlug,
	leagueId,
}: {
	db: DrizzleDB;
	seasonSlug: string;
	leagueId?: string;
}) => {
	const whereConditions = [eq(season.slug, seasonSlug)];
	if (leagueId) {
		whereConditions.push(eq(season.leagueId, leagueId));
	}

	const [comp] = await db
		.select()
		.from(season)
		.where(and(...whereConditions));

	if (!comp) {
		throw new Error("Season not found");
	}
	return comp;
};

export const findActive = async ({ db, leagueId }: { db: DrizzleDB; leagueId: string }) => {
	const now = new Date();
	const [comp] = await db
		.select(getTableColumns(season))
		.from(season)
		.innerJoin(organization, eq(organization.id, season.leagueId))
		.where(
			and(
				eq(season.leagueId, leagueId),
				eq(season.closed, false),
				lt(season.startDate, now),
				or(isNull(season.endDate), gt(season.endDate, now))
			)
		);
	return comp ?? null;
};

export const findAllActive = async ({ db, leagueId }: { db: DrizzleDB; leagueId: string }) => {
	const now = new Date();
	return db
		.select(getTableColumns(season))
		.from(season)
		.innerJoin(organization, eq(organization.id, season.leagueId))
		.where(
			and(
				eq(season.leagueId, leagueId),
				eq(season.closed, false),
				lt(season.startDate, now),
				or(isNull(season.endDate), gt(season.endDate, now))
			)
		)
		.orderBy(desc(season.startDate));
};

export const getAll = async ({ db, leagueId }: { db: DrizzleDB; leagueId: string }) =>
	db
		.select(getTableColumns(season))
		.from(season)
		.where(eq(season.leagueId, leagueId))
		.orderBy(desc(season.startDate));

export const update = async ({
	db,
	userId,
	seasonId,
	...rest
}: SeasonEditInput & { db: DrizzleDB }) => {
	const now = new Date();
	const [comp] = await db
		.update(season)
		.set({
			updatedAt: now,
			updatedBy: userId,
			...rest,
		})
		.where(eq(season.id, seasonId))
		.returning();

	return comp;
};

export const updateClosedStatus = async ({
	db,
	seasonId,
	userId,
	closed,
}: {
	db: DrizzleDB;
	seasonId: string;
	userId: string;
	closed: boolean;
}) => {
	const now = new Date();
	const [comp] = await db
		.update(season)
		.set({
			closed,
			updatedAt: now,
			updatedBy: userId,
		})
		.where(eq(season.id, seasonId))
		.returning();

	return comp;
};

export const create = async ({ db, ...input }: SeasonCreateInput & { db: DrizzleDB }) => {
	const slug = input.slug || (await slugifySeasonName({ db, name: input.name }));
	const now = new Date();
	const seasonId = input.id ?? newId("season");

	return withTransaction(db, async (tx) => {
		const isEloBased = input.scoreType === "elo" || input.scoreType === "1-v-n-elo";
		const values = isEloBased
			? {
					id: seasonId,
					name: input.name,
					slug,
					leagueId: input.leagueId,
					startDate: input.startDate,
					endDate: input.endDate ?? null,
					initialScore: input.initialScore,
					kFactor: input.kFactor,
					scoreType: input.scoreType as (typeof scoreType)[number],
					rounds: null,
					createdAt: now,
					updatedAt: now,
					createdBy: input.userId,
					updatedBy: input.userId,
					archived: false,
					closed: false,
				}
			: {
					id: seasonId,
					name: input.name,
					slug,
					leagueId: input.leagueId,
					startDate: input.startDate,
					endDate: input.endDate ?? null,
					initialScore: 0,
					kFactor: -1,
					rounds: input.rounds ?? null,
					scoreType: "3-1-0" as const,
					createdAt: now,
					updatedAt: now,
					createdBy: input.userId,
					updatedBy: input.userId,
					archived: false,
					closed: false,
				};

		const comps = await tx.insert(season).values(values).returning();
		const comp = comps[0];

		// Get all enabled players from organization and create season players
		const players = await tx
			.select({ id: player.id })
			.from(player)
			.where(and(eq(player.leagueId, input.leagueId), eq(player.disabled, false)));

		const seasonPlayerValues = players.map((p) => ({
			id: newId("seasonPlayer"),
			disabled: false,
			score: comp.initialScore,
			playerId: p.id,
			seasonId: comp.id,
			createdAt: now,
			updatedAt: now,
		}));

		if (seasonPlayerValues.length > 0) {
			const SEASON_PLAYER_BATCH_SIZE = 10;
			for (let i = 0; i < seasonPlayerValues.length; i += SEASON_PLAYER_BATCH_SIZE) {
				const batch = seasonPlayerValues.slice(i, i + SEASON_PLAYER_BATCH_SIZE);
				await tx.insert(seasonPlayer).values(batch);
			}
		}

		// If 3-1-0 with rounds, generate fixtures
		if (input.scoreType === "3-1-0" && input.rounds && input.rounds > 0) {
			const seasonPlayerIds = seasonPlayerValues.map((cp) => cp.id);
			const fixturesList: (typeof fixture.$inferInsert)[] = [];

			const playersList: Array<string | null> = [...seasonPlayerIds];
			if (playersList.length % 2 !== 0) {
				playersList.push(null);
			}

			const totalPlayers = playersList.length;
			const matchesPerRound = totalPlayers / 2;
			const roundsPerCompleteTournament = totalPlayers - 1;

			for (let tournament = 0; tournament < input.rounds; tournament++) {
				let tournamentPlayers = [...playersList];

				for (let roundNum = 0; roundNum < roundsPerCompleteTournament; roundNum++) {
					const actualRound = tournament * roundsPerCompleteTournament + roundNum;
					const roundFixtures: Array<{ homeId: string; awayId: string }> = [];

					for (let i = 0; i < matchesPerRound; i++) {
						const homeId = tournamentPlayers[i];
						const awayId = tournamentPlayers[totalPlayers - 1 - i];

						if (homeId !== null && awayId !== null) {
							const finalHomeId = tournament % 2 === 0 ? homeId : awayId;
							const finalAwayId = tournament % 2 === 0 ? awayId : homeId;
							roundFixtures.push({ homeId: finalHomeId, awayId: finalAwayId });
						}
					}

					for (const f of roundFixtures) {
						fixturesList.push({
							id: newId("fixture"),
							homePlayerId: f.homeId,
							awayPlayerId: f.awayId,
							seasonId: comp.id,
							round: actualRound + 1,
							createdAt: now,
							updatedAt: now,
							matchId: null,
							deletedAt: null,
						});
					}

					const rotatedPlayers = [
						tournamentPlayers[0],
						tournamentPlayers[totalPlayers - 1],
						...tournamentPlayers.slice(1, totalPlayers - 1),
					];
					tournamentPlayers = rotatedPlayers;
				}
			}

			if (fixturesList.length > 0) {
				const BATCH_SIZE = 10;
				for (let i = 0; i < fixturesList.length; i += BATCH_SIZE) {
					const batch = fixturesList.slice(i, i + BATCH_SIZE);
					await tx.insert(fixture).values(batch);
				}
			}
		}

		return comp;
	});
};

export const findFixtures = async ({ db, seasonId }: { db: DrizzleDB; seasonId: string }) => {
	return db
		.select({
			id: fixture.id,
			round: fixture.round,
			seasonId: fixture.seasonId,
			matchId: fixture.matchId,
			homePlayerId: fixture.homePlayerId,
			awayPlayerId: fixture.awayPlayerId,
			createdAt: fixture.createdAt,
			updatedAt: fixture.updatedAt,
			homeScore: match.homeScore,
			awayScore: match.awayScore,
		})
		.from(fixture)
		.leftJoin(match, eq(fixture.matchId, match.id))
		.where(eq(fixture.seasonId, seasonId))
		.orderBy(asc(fixture.round), asc(fixture.createdAt), asc(fixture.homePlayerId));
};

export const findFixtureById = async ({
	db,
	seasonId,
	fixtureId,
}: {
	db: DrizzleDB;
	seasonId: string;
	fixtureId: string;
}) => {
	const [f] = await db
		.select()
		.from(fixture)
		.where(and(eq(fixture.seasonId, seasonId), eq(fixture.id, fixtureId)))
		.limit(1);
	return f;
};

export const assignMatchToFixture = async ({
	db,
	seasonId,
	fixtureId,
	matchId,
}: {
	db: DrizzleDB;
	seasonId: string;
	fixtureId: string;
	matchId: string;
}) => {
	await db
		.update(fixture)
		.set({ matchId })
		.where(and(eq(fixture.seasonId, seasonId), eq(fixture.id, fixtureId)));
};

export const slugifySeasonName = async ({ db, name }: { db: DrizzleDB; name: string }) => {
	const rootSlug = slugifyWithCustomReplacement(name);

	const findAvailableSlug = async (counter = 0): Promise<string> => {
		const checkBatchSize = 10;
		const slugsToCheck = Array.from({ length: checkBatchSize }, (_, i) => {
			const index = counter + i;
			return index === 0 ? rootSlug : `${rootSlug}-${index}`;
		});

		// Single query to check all slugs at once
		const existingSlugs = await db
			.select({ slug: season.slug })
			.from(season)
			.where(sql`${season.slug} IN ${slugsToCheck}`);

		const existingSet = new Set(existingSlugs.map((r) => r.slug));
		const availableSlug = slugsToCheck.find((slug) => !existingSet.has(slug));

		if (availableSlug) {
			return availableSlug;
		}

		return findAvailableSlug(counter + checkBatchSize);
	};

	return findAvailableSlug();
};

