function MobileStandingRow({
	item,
	leagueSlug,
	onClick,
	dimmed,
}: {
	item: {
		id: string;
		name: string;
		image: string | null;
		playerId: string;
		score: number;
		matchCount: number;
		winCount: number;
		pointDiff: number;
		form: ("W" | "D" | "L")[] | undefined;
	};
	leagueSlug?: string;
	onClick?: () => void;
	dimmed?: boolean;
}) {
	const winPct = item.matchCount > 0 ? Math.round((item.winCount / item.matchCount) * 100) : 0;
	const streak = calculateStreak(item.form);

	return (
		<div
