											/>
											<span
												className="font-medium truncate"
												data-testid={`standing-name-${item.id}`}
											>
												{item.name}
											</span>
										</div>
									</TableCell>
									<TableCell
										className="text-center text-muted-foreground"
										data-testid={`standing-mp-${item.id}`}
									>
										{item.matchCount}
									</TableCell>
